const body = $input.first().json.body;
const af = body.afiliado;
const nombre = af.nombre || 'Sin nombre';
const correo = af.correo || 'N/A';
const doc = af.documento || 'N/A';
const obj = af.objetivo || 'No especificado';

const msg = `🏢 *Nuevo Afiliado — MetaFit*\n\n👤 Nombre: *${nombre}*\n📧 Correo: ${correo}\n🪪 Documento: ${doc}\n🎯 Objetivo: ${obj}\n\nBienvenido al equipo. 💪`;

return [{ json: { chat_id: '8824635784', text: msg, parse_mode: 'Markdown' } }];

const body = $input.first().json.body;
const p = body.pago;
const af = body.afiliado;
const nombre = af.nombre || 'Afiliado';
const valor = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP' }).format(p.valor_pagado);
const factura = `FAC-${new Date().getFullYear()}-${String(p.id_pago).padStart(4, '0')}`;

const msg = `💰 *Pago Registrado — MetaFit*\n\n👤 Afiliado: *${nombre}*\n📋 Factura: ${factura}\n💵 Valor: *${valor}\n📅 Fecha: ${p.fecha_pago}\n💳 Método: ${p.metodo_pago}\n📆 Vence: ${p.fecha_vencimiento}`;

return [{ json: { chat_id: '8824635784', text: msg, parse_mode: 'Markdown' } }];

const body = $input.first().json.body;
const af = body.afiliado;
const c = body.ciclo;
const nombre = af.nombre || 'Afiliado';

const msg = `🏋️ *Rutina Asignada — MetaFit*\n\n👤 Afiliado: *${nombre}*\n📅 Ciclo: ${c.fecha_inicio} → ${c.fecha_fin}\n\nSe le ha asignado un nuevo plan de entrenamiento. 💪`;

return [{ json: { chat_id: '8824635784', text: msg, parse_mode: 'Markdown' } }];
